function solve(nums, k) {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let sum = 0;
    for (let j = i; j < nums.length; j++) {
      sum += nums[j];
      if (sum === k) count++;
    }
  }
  return count;
}

function solve(nums, k) {
  const freq = new Map([[0, 1]]);
  let sum = 0, count = 0;
  for (const n of nums) {
    sum += n;
    if (freq.has(sum - k)) count += freq.get(sum - k);
    freq.set(sum, (freq.get(sum) || 0) + 1);
  }
  return count;
}

